public void SortColorsCounting(int[] nums)
{
    int zeros = 0, ones = 0, twos = 0;

    foreach (int v in nums)
    {
        if (v == 0) zeros++;
        else if (v == 1) ones++;
        else twos++;
    }

    int i = 0;
    while (zeros-- > 0) nums[i++] = 0;
    while (ones-- > 0) nums[i++] = 1;
    while (twos-- > 0) nums[i++] = 2;
}

public void SortColors(int[] nums)
{
    int low = 0;                        // next position for a 0
    int mid = 0;                        // current element being examined
    int high = nums.Length - 1;         // next position for a 2

    while (mid <= high)
    {
        if (nums[mid] == 0)
        {
            Swap(nums, low, mid);
            low++;
            mid++;      // nums[mid] now holds a 1, which is already in place
        }
        else if (nums[mid] == 1)
        {
            mid++;      // 1s are always correct where they are
        }
        else
        {
            Swap(nums, mid, high);
            high--;     // do NOT advance mid: the swapped-in value is unexamined
        }
    }
}

private static void Swap(int[] nums, int i, int j)
{
    (nums[i], nums[j]) = (nums[j], nums[i]);
}

public void SortColors(int[] nums)
{
    int low = 0, mid = 0, high = nums.Length - 1;

    while (mid <= high)
    {
        switch (nums[mid])
        {
            case 0:
                Swap(nums, low++, mid++);
                break;
            case 1:
                mid++;
                break;
            default:
                Swap(nums, mid, high--);
                break;
        }
    }
}

private static void Swap(int[] a, int i, int j) => (a[i], a[j]) = (a[j], a[i]);
